import {
  Body,
  Controller,
  GatewayTimeoutException,
  Post,
  ServiceUnavailableException,
} from '@nestjs/common';
import { OrdersRepository, type PlaceOrderDto } from './orders.repository.js';

@Controller('orders')
export class OrdersController {
  constructor(private readonly orders: OrdersRepository) {}

  @Post()
  async create(@Body() dto: PlaceOrderDto) {
    const order = await this.orders.insert(dto); // ≈ 20 мс

    await this.post('http://localhost:3001/charges', { // ≈ 150 мс
      orderId: order.id,
      total: dto.total,
    });
    await this.post('http://localhost:3002/emails', { // ≈ 300 мс
      template: 'order-placed',
      orderId: order.id,
    });

    return { orderId: order.id, status: 'placed' };
  }

  private async post(url: string, body: unknown): Promise<void> {
    let res: Response;
    try {
      res = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(2000),
      });
    } catch (error) {
      if (error instanceof DOMException && error.name === 'TimeoutError') {
        throw new GatewayTimeoutException(`${url}: нет ответа за 2 с`);
      }
      throw new ServiceUnavailableException(`${url}: нет соединения`);
    }
    if (!res.ok) {
      throw new ServiceUnavailableException(`${url}: ответ ${res.status}`);
    }
  }
}

