export abstract class EventPublisher {
  /** Передать сообщение брокеру. Промис выполняется, когда брокер его принял. */
  abstract publish(type: string, body: object): Promise<void>;
}

import { Body, Controller, Post } from '@nestjs/common';
import { EventPublisher } from './events/event-publisher.js';
import { OrdersRepository, type PlaceOrderDto } from './orders.repository.js';

@Controller('orders')
export class OrdersController {
  constructor(
    private readonly orders: OrdersRepository,
    private readonly events: EventPublisher,
  ) {}

  @Post()
  async create(@Body() dto: PlaceOrderDto) {
    const order = await this.orders.insert(dto);
    await this.events.publish('order.placed', {
      orderId: order.id,
      customerId: dto.customerId,
      items: dto.items,
      total: dto.total,
    });
    return { orderId: order.id, status: 'placed' };
  }
}

