type Service = 'payments' | 'notifications';
const services: Service[] = ['payments', 'notifications'];
const up: Record<Service, boolean> = { payments: true, notifications: false };

// Синхронно: вызываем по очереди, каждый должен работать прямо сейчас
function placeSync(orderId: string): void {
  for (const service of services) {
    if (!up[service]) {
      console.log(`${orderId}: клиенту ошибка, ${service} недоступен`);
      return;
    }
    console.log(`${orderId}: ${service} обработал`);
  }
  console.log(`${orderId}: клиенту ответ «принят»`);
}

// Через брокер: сообщение ждёт каждого получателя
const waiting: Record<Service, string[]> = { payments: [], notifications: [] };

function placeAsync(orderId: string): void {
  for (const service of services) waiting[service].push(orderId);
  console.log(`${orderId}: клиенту ответ «принят»`);
}

function deliver(service: Service): void {
  if (!up[service]) return; // получатель выключен, сообщения ждут
  for (const orderId of waiting[service].splice(0)) {
    console.log(`${orderId}: ${service} обработал`);
  }
}

placeSync('A-1');
placeAsync('A-2');
deliver('payments');
deliver('notifications');
up.notifications = true; // notifications перезапустили
deliver('notifications');

