export type Message = { id: number; body: string };

export class TinyQueue {
  private ready: Message[] = []; // ждут выдачи, по порядку поступления
  private unacked = new Map<number, { msg: Message; consumer: string }>(); // выданы, ждут ack
  private nextId = 1;

  publish(body: string): void {
    this.ready.push({ id: this.nextId++, body }); // в хвост очереди
  }

  // Выдать потребителю следующее сообщение из головы очереди
  consume(consumer: string): Message | undefined {
    const msg = this.ready.shift();
    if (msg) this.unacked.set(msg.id, { msg, consumer }); // брокер помнит, кому выдал
    return msg;
  }

  // Обработано: сообщение удаляется навсегда
  ack(id: number): void {
    this.unacked.delete(id);
  }

  // Не обработано: сообщение возвращается в голову очереди
  nack(id: number): void {
    const entry = this.unacked.get(id);
    if (!entry) return;
    this.unacked.delete(id);
    this.ready.unshift(entry.msg);
  }

  // Потребитель отключился: всё, что он не подтвердил, возвращается в очередь
  disconnect(consumer: string): void {
    const back = [...this.unacked.values()].filter((e) => e.consumer === consumer);
    for (const e of back) this.unacked.delete(e.msg.id);
    this.ready.unshift(...back.map((e) => e.msg));
  }

  stats() {
    return { ready: this.ready.length, unacked: this.unacked.size };
  }
}

