export type Entry = { offset: number; body: string };

export class TinyLog {
  private entries: Entry[] = [];
  private positions = new Map<string, number>(); // группа → следующий оффсет к чтению

  // Дописать запись в конец; оффсет — её номер в логе
  append(body: string): number {
    const offset = this.entries.length;
    this.entries.push({ offset, body });
    return offset;
  }

  // Прочитать записи начиная с fromOffset; лог при этом не меняется
  read(fromOffset: number, max = 100): Entry[] {
    return this.entries.slice(fromOffset, fromOffset + max);
  }

  // Группа сохраняет позицию: оффсет следующей записи, которую она прочитает
  commit(group: string, offset: number): void {
    this.positions.set(group, offset);
  }

  // В этой модели группа без сохранённой позиции начинает с начала
  position(group: string): number {
    return this.positions.get(group) ?? 0;
  }
}

import { TinyLog } from './tiny-log.js';

const log = new TinyLog();
for (const orderId of [101, 102, 103]) log.append(`заказ ${orderId}`);

// Один шаг потребителя группы
function poll(group: string, max = 100): void {
  const from = log.position(group);              // 1. взять свою позицию
  const batch = log.read(from, max);             // 2. прочитать записи с неё
  const done = batch.map((e) => `[${e.offset}] ${e.body}`); // 3. «обработать»
  log.commit(group, from + batch.length);        // 4. сохранить новую позицию
  console.log(`${group}: ${done.join(', ') || 'нового нет'} → позиция ${log.position(group)}`);
}

poll('payments');          // payments успевает всё
poll('notifications', 1);  // notifications медленнее: взял одну запись
log.append('заказ 104');   // orders дописывает новое событие
poll('payments');
poll('notifications');
poll('payments');          // прочитанное не исчезло, но позиция уже в конце
