// Упрощённая модель сравнения в обменнике типа topic
function matches(pattern: string, key: string): boolean {
  const p = pattern.split('.');
  const k = key === '' ? [] : key.split('.'); // пустой ключ — ноль слов
  const go = (i: number, j: number): boolean => {
    if (i === p.length) return j === k.length; // шаблон кончился: ключ тоже должен
    if (p[i] === '#') {
      // # съедает 0, 1, 2… слов: пробуем каждый вариант
      for (let next = j; next <= k.length; next++) if (go(i + 1, next)) return true;
      return false;
    }
    if (j === k.length) return false; // слова ключа кончились раньше шаблона
    return (p[i] === '*' || p[i] === k[j]) && go(i + 1, j + 1);
  };
  return go(0, 0);
}

for (const key of ['order.placed', 'order', 'order.paid.card']) {
  console.log(key, matches('order.*', key), matches('order.#', key));
}

