import { type Channel, connect } from 'amqplib';

const quorum = { 'x-queue-type': 'quorum' };

// orders при старте объявляет свой обменник
export async function setupOrders(channel: Channel) {
  await channel.assertExchange('orders.events', 'topic', { durable: true });
}

// payments объявляет свою очередь и привязывает её к обменнику orders
export async function setupPayments(channel: Channel) {
  await channel.assertExchange('orders.events', 'topic', { durable: true });
  await channel.assertQueue('payments.order-placed', { durable: true, arguments: quorum });
  await channel.bindQueue('payments.order-placed', 'orders.events', 'order.placed');
}

// notifications: одна очередь на все события заказа
export async function setupNotifications(channel: Channel) {
  await channel.assertExchange('orders.events', 'topic', { durable: true });
  await channel.assertQueue('notifications.order-events', { durable: true, arguments: quorum });
  await channel.bindQueue('notifications.order-events', 'orders.events', 'order.*');
}

const connection = await connect('amqp://shop:shop@localhost');
const channel = await connection.createChannel();
await setupOrders(channel);
await setupPayments(channel);
await setupNotifications(channel);

