/** Один долговечный обменник типа topic на производителя: `<producer>.events`. */
export const eventsExchange = (producer: Producer) => `${producer}.events`;

/** Очереди принадлежат потребителю: `<consumer>.<name>`. */
export function defineQueue(
  consumer: Producer,
  name: string,
  bindings: { producer: Producer; types: string[] }[],
) {
  return {
    name: `${consumer}.${name}`,
    bindings: bindings.flatMap(({ producer, types }) =>
      types.map((routingKey) => ({ exchange: eventsExchange(producer), routingKey })),
    ),
  };
}

