import { randomUUID } from 'node:crypto';
import { Inject, Injectable } from '@nestjs/common';
import type { ClientProxy } from '@nestjs/microservices';
import { lastValueFrom } from 'rxjs';

export interface PlaceOrderDto {
  customerId: string;
  items: { sku: string; qty: number }[];
  total: { amount: string; currency: string };
}

@Injectable()
export class OrdersService {
  constructor(@Inject('NOTIFICATIONS') private readonly notifications: ClientProxy) {}

  async place(dto: PlaceOrderDto) {
    const order = { orderId: randomUUID(), ...dto };
    // здесь заказ сохраняется в базе; как не потерять событие при сбое — глава 10
    await lastValueFrom(this.notifications.emit('order.placed', order));
    return { orderId: order.orderId };
  }
}

