import {
  type DynamicModule,
  Global,
  Inject,
  Injectable,
  type InjectionToken,
  Logger,
  Module,
  type OnApplicationShutdown,
} from '@nestjs/common';
import { type AmqpConnectionManager, type ChannelWrapper, connect } from 'amqp-connection-manager';
import type { ConfirmChannel, ConsumeMessage } from 'amqplib';

export type MessagingOptions = { url: string; service: string };

/** Событие, которое публикует сервис. */
export type ShopEvent = {
  eventId: string;    // идентификатор сообщения (глава 1): при повторе тот же
  type: string;       // тип события, он же ключ маршрутизации: order.placed
  occurredAt: string; // когда произошло, ISO 8601
  payload: unknown;   // данные события
};

export type QueueSpec = {
  name: string; // имя очереди: <потребитель>.<имя>, как в главе 3
  bindings: { exchange: string; routingKey: string }[];
  prefetch: number;
};

export type Handler = (body: unknown, message: ConsumeMessage) => Promise<void>;

const MESSAGING_OPTIONS = Symbol('MESSAGING_OPTIONS');

@Injectable()
export class Messaging implements OnApplicationShutdown {
  private readonly logger = new Logger(Messaging.name);
  private readonly connection: AmqpConnectionManager;
  private readonly publisher: ChannelWrapper;
  private readonly consumers: ChannelWrapper[] = [];
  private readonly inFlight = new Set<Promise<void>>();

  constructor(@Inject(MESSAGING_OPTIONS) options: MessagingOptions) {
    this.connection = connect([options.url], {
      heartbeatIntervalInSeconds: 15, // контрольные сигналы раз в 15 с
      reconnectTimeInSeconds: 2,      // пауза перед новой попыткой
      connectionOptions: { clientProperties: { connection_name: options.service } },
    });
    this.connection.on('disconnect', ({ err }) =>
      this.logger.warn(`соединение потеряно: ${err?.message}`),
    );
    this.publisher = this.connection.createChannel({
      confirm: true,
      // свой обменник сервиса: orders.events
      setup: (ch: ConfirmChannel) =>
        ch.assertExchange(`${options.service}.events`, 'topic', { durable: true }),
    });
  }

  /** Выполняется, когда брокер подтвердил сообщение. */
  async publish(exchange: string, event: ShopEvent) {
    await this.publisher.publish(exchange, event.type, Buffer.from(JSON.stringify(event)), {
      persistent: true,
      contentType: 'application/json',
      messageId: event.eventId,
      type: event.type,
      timestamp: Math.floor(Date.parse(event.occurredAt) / 1000),
    });
  }

  async subscribe(spec: QueueSpec, handler: Handler) {
    const channel = this.connection.createChannel({
      confirm: true,
      // выполняется после каждого подключения, на новом канале
      setup: async (ch: ConfirmChannel) => {
        for (const { exchange } of spec.bindings)
          await ch.assertExchange(exchange, 'topic', { durable: true });
        await ch.assertQueue(spec.name, { durable: true, arguments: { 'x-queue-type': 'quorum' } });
        for (const { exchange, routingKey } of spec.bindings)
          await ch.bindQueue(spec.name, exchange, routingKey);
      },
    });
    this.consumers.push(channel);
    await channel.waitForConnect();
    await channel.consume(
      spec.name,
      (message) => {
        const work = this.handle(channel, message, handler);
        this.inFlight.add(work);
        void work.finally(() => this.inFlight.delete(work));
      },
      { prefetch: spec.prefetch },
    );
  }

  private async handle(channel: ChannelWrapper, message: ConsumeMessage, handler: Handler) {
    try {
      await handler(JSON.parse(message.content.toString('utf8')), message);
      channel.ack(message);
    } catch (err) {
      this.logger.error(`${message.properties.messageId}: ${(err as Error).message}`);
      channel.nack(message, false, false); // повторы с паузой — глава 5
    }
  }

  isConnected() {
    return this.connection.isConnected();
  }

  async onApplicationShutdown() {
    await Promise.allSettled(this.consumers.map((c) => c.cancelAll())); // не брать новые
    await Promise.allSettled([...this.inFlight]);                       // доделать начатые
    await Promise.allSettled(this.consumers.map((c) => c.close()));
    await this.publisher.close();
    await this.connection.close();
  }
}

@Global()
@Module({})
export class MessagingModule {
  static forRootAsync(options: {
    inject?: InjectionToken[];
    useFactory: (...args: any[]) => MessagingOptions | Promise<MessagingOptions>;
  }): DynamicModule {
    return {
      module: MessagingModule,
      providers: [
        { provide: MESSAGING_OPTIONS, inject: options.inject ?? [], useFactory: options.useFactory },
        Messaging,
      ],
      exports: [Messaging],
    };
  }
}

