import { Injectable } from '@nestjs/common';
import { PermanentError, type ShopEvent } from './messaging.js';
import { GatewayError, PaymentGateway } from './payment-gateway.js';

type OrderPlaced = {
  orderId: string;
  customerId: string;
  total: { amount: string; currency: string };
};

@Injectable()
export class OrderPlacedHandler {
  constructor(private readonly gateway: PaymentGateway) {}

  async handle(body: unknown): Promise<void> {
    const event = body as ShopEvent | null; // событие из главы 4
    const order = toOrderPlaced(event?.payload); // неверные данные — PermanentError
    try {
      // Ключ идемпотентности: повтор по тому же заказу не спишет деньги дважды
      await this.gateway.capture({ idempotencyKey: order.orderId, amount: order.total });
    } catch (error) {
      if (error instanceof GatewayError && error.isClientError()) {
        throw new PermanentError(`платёж отклонён: ${error.message}`, { cause: error });
      }
      throw error; // сеть, таймаут, 5xx, 429 — временные, пусть повторят позже
    }
  }
}

function toOrderPlaced(payload: unknown): OrderPlaced {
  const order = payload as Partial<OrderPlaced> | null;
  if (
    typeof order?.orderId !== 'string' ||
    typeof order.customerId !== 'string' ||
    typeof order.total?.amount !== 'string'
  ) {
    throw new PermanentError('в order.placed нет orderId, customerId или total.amount');
  }
  if (order.total.currency !== 'RUB') {
    throw new PermanentError(`валюта ${order.total.currency} не поддерживается`);
  }
  return order as OrderPlaced;
}

import { type Channel, connect } from 'amqplib';

const url = process.env.AMQP_URL ?? 'amqp://shop:shop@localhost';
const QUEUE = 'payments.order-placed';
const DLQ = 'payments.order-placed.dlq';
const quorum = { 'x-queue-type': 'quorum' };

const connection = await connect(url);
const channel = await connection.createConfirmChannel();

await channel.assertExchange('orders.events', 'topic', { durable: true });
await channel.assertQueue(DLQ, { durable: true, arguments: quorum });
await channel.assertQueue(QUEUE, {
  durable: true,
  arguments: {
    ...quorum,
    'x-dead-letter-exchange': '', // обменник по умолчанию...
    'x-dead-letter-routing-key': DLQ, // ...доставит прямо в очередь с этим именем
  },
});
await channel.bindQueue(QUEUE, 'orders.events', 'order.placed');

// Битое сообщение: JSON обрывается на полуслове
channel.publish('orders.events', 'order.placed', Buffer.from('{"orderId": "A-1'), {
  persistent: true,
  messageId: 'msg-1',
});
await channel.waitForConfirms();

await channel.consume(QUEUE, (message) => {
  if (!message) return;
  try {
    JSON.parse(message.content.toString('utf8'));
    channel.ack(message);
  } catch {
    channel.nack(message, false, false); // без requeue: сообщение «умирает»
  }
});

// Что лежит в DLQ
const dead = await nextMessage(channel, DLQ);
const headers = dead.properties.headers ?? {};
const [death] = headers['x-death'] ?? [];
console.log(`messageId: ${dead.properties.messageId}`);
console.log(`x-first-death-reason: ${headers['x-first-death-reason']}`);
console.log(`x-death: queue=${death?.queue}, reason=${death?.reason}, count=${death?.count}`);
console.log(`         exchange=${death?.exchange}, routing-keys=${death?.['routing-keys']}`);
channel.ack(dead);
await channel.close();
await connection.close();

async function nextMessage(ch: Channel, queue: string) {
  for (;;) {
    const message = await ch.get(queue);
    if (message) return message;
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
}

