export type QueueSpec = {
  name: string; // имя очереди: <потребитель>.<имя>, как в главе 3
  bindings: { exchange: string; routingKey: string }[];
  prefetch: number;
  /** Новое поле: ступени повторов — сколько ждать перед попыткой 1, 2, 3… */
  retryDelaysMs: readonly number[];
};

/** Вторым аргументом теперь приходит номер попытки, а не сырое сообщение. */
export type Handler = (body: unknown, context: { attempt: number }) => Promise<void>;

export const retryQueueName = (queue: string, tier: number) => `${queue}.retry.${tier}`;
export const deadLetterQueueName = (queue: string) => `${queue}.dlq`;

/** Заголовок со счётчиком уже сделанных попыток. */
export const ATTEMPT_HEADER = 'x-attempt';

const quorum = { 'x-queue-type': 'quorum' } as const;

async subscribe(spec: QueueSpec, handler: Handler) {
  const dlq = deadLetterQueueName(spec.name);
  const channel = this.connection.createChannel({
    confirm: true,
    setup: async (ch: ConfirmChannel) => {
      await ch.assertQueue(dlq, { durable: true, arguments: quorum });
      await ch.assertQueue(spec.name, {
        durable: true,
        // Страховка: что брокер сам признает мёртвым, тоже попадёт в DLQ
        arguments: {
          ...quorum,
          'x-dead-letter-exchange': '',
          'x-dead-letter-routing-key': dlq,
        },
      });
      for (const { exchange, routingKey } of spec.bindings) {
        await ch.assertExchange(exchange, 'topic', { durable: true });
        await ch.bindQueue(spec.name, exchange, routingKey);
      }
      for (const [tier, delay] of spec.retryDelaysMs.entries()) {
        await ch.assertQueue(retryQueueName(spec.name, tier), {
          durable: true,
          arguments: {
            ...quorum,
            'x-message-ttl': delay, // сколько ждать на этой ступени
            'x-dead-letter-exchange': '', // по истечении — в обменник по умолчанию
            'x-dead-letter-routing-key': spec.name, // а он вернёт в рабочую очередь
          },
        });
      }
    },
  });
  this.consumers.push(channel);
  await channel.waitForConnect();
  await channel.consume(
    spec.name,
    (message) => {
      const work = this.handle(channel, spec, message, handler);
      this.inFlight.add(work); // как в главе 4: остановка дождётся начатых обработок
      void work.finally(() => this.inFlight.delete(work));
    },
    { prefetch: spec.prefetch },
  );
}

private async handle(
  channel: ChannelWrapper,
  spec: QueueSpec,
  message: ConsumeMessage,
  handler: Handler,
) {
  const attempt = Number(message.properties.headers?.[ATTEMPT_HEADER] ?? 0);
  let body: unknown;
  try {
    body = JSON.parse(message.content.toString('utf8'));
  } catch {
    const dlq = deadLetterQueueName(spec.name);
    return this.moveTo(channel, message, dlq, attempt, 'невалидный JSON');
  }
  try {
    await handler(body, { attempt });
    channel.ack(message);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    const exhausted = attempt >= spec.retryDelaysMs.length;
    const target =
      error instanceof PermanentError || exhausted
        ? deadLetterQueueName(spec.name)
        : retryQueueName(spec.name, attempt);
    this.logger.warn(`${spec.name}: попытка ${attempt} не удалась (${reason}) → ${target}`);
    await this.moveTo(channel, message, target, attempt + 1, reason);
  }
}

/** Копия в другую очередь с подтверждением брокера — и только потом ack оригинала. */
private async moveTo(
  channel: ChannelWrapper,
  message: ConsumeMessage,
  queue: string,
  attempt: number,
  reason: string,
) {
  try {
    await channel.sendToQueue(queue, message.content, {
      ...message.properties,
      persistent: true,
      headers: {
        ...message.properties.headers,
        [ATTEMPT_HEADER]: attempt,
        'x-last-error': reason.slice(0, 500),
      },
    });
    channel.ack(message);
  } catch (error) {
    // Переложить не вышло: пусть брокер доставит сообщение ещё раз, чем потерять его
    this.logger.error(`не удалось переложить сообщение в ${queue}: ${(error as Error).message}`);
    channel.nack(message, false, true);
  }
}

