import { Injectable, type OnApplicationBootstrap, type OnApplicationShutdown } from '@nestjs/common';
import { type Consumer, Kafka } from 'kafkajs';
import type { OrderPlaced } from '../shop/order-placed.js';
import { OrderStats } from './order-stats.js';

@Injectable()
export class OrdersBatchConsumer implements OnApplicationBootstrap, OnApplicationShutdown {
  private readonly consumer: Consumer;

  constructor(private readonly stats: OrderStats) {
    const kafka = new Kafka({ clientId: 'analytics', brokers: ['localhost:9092'] });
    this.consumer = kafka.consumer({ groupId: 'analytics' });
  }

  async onApplicationBootstrap() {
    await this.consumer.connect();
    await this.consumer.subscribe({ topics: ['orders'] });
    await this.consumer.run({
      partitionsConsumedConcurrently: 3, // до трёх партиций одновременно
      eachBatchAutoResolve: false, // обработанное отмечаем сами
      eachBatch: async ({ batch, resolveOffset, heartbeat, isRunning, isStale }) => {
        // пачка — записи одной партиции в порядке оффсетов
        for (let i = 0; i < batch.messages.length; i += 100) {
          if (!isRunning() || isStale()) return; // остаток прочитаем снова
          const chunk = batch.messages.slice(i, i + 100);
          await this.stats.recordMany(chunk.flatMap((m) => this.parse(m.value)));
          resolveOffset(chunk.at(-1)!.offset); // всё до этой записи обработано
          await heartbeat();
        }
      },
    });
  }

  async onApplicationShutdown() {
    await this.consumer.disconnect(); // дождаться пачки, закоммитить, выйти из группы
  }

  private parse(value: Buffer | null): OrderPlaced[] {
    try {
      return value ? [JSON.parse(value.toString()) as OrderPlaced] : [];
    } catch {
      return []; // SyntaxError не отдаём kafkajs: потребитель встанет до перезапуска процесса
    }
  }
}

