import { Injectable, type OnApplicationBootstrap, type OnApplicationShutdown } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { type Consumer, type EachMessagePayload, Kafka, type Producer } from 'kafkajs';
import type { OrderPlaced } from '../shop/order-placed.js';

// группа названа по обработчику, а не по топику payments, в который он пишет
const GROUP_ID = 'payments-processor';

@Injectable()
export class PaymentsProcessor implements OnApplicationBootstrap, OnApplicationShutdown {
  private readonly consumer: Consumer;
  private readonly producer: Producer;

  constructor(config: ConfigService) {
    const kafka = new Kafka({ clientId: 'payments', brokers: ['localhost:9092'] });
    // readUncommitted: false по умолчанию — только зафиксированные записи
    this.consumer = kafka.consumer({ groupId: GROUP_ID });
    this.producer = kafka.producer({
      // постоянное имя экземпляра (payments-processor-0, -1…), а не случайное при старте
      transactionalId: `${GROUP_ID}-${config.getOrThrow<string>('INSTANCE_ID')}`,
      idempotent: true,
      maxInFlightRequests: 1,
    });
  }

  async onApplicationBootstrap() {
    await this.producer.connect();
    await this.consumer.connect();
    await this.consumer.subscribe({ topics: ['orders'], fromBeginning: true });
    await this.consumer.run({
      autoCommit: false, // оффсеты уходят в транзакции, а не отдельным коммитом
      eachMessage: (payload) => this.process(payload),
    });
  }

  private async process({ topic, partition, message }: EachMessagePayload) {
    const tx = await this.producer.transaction();
    try {
      if (message.headers?.type?.toString() === 'order.placed') {
        const order = JSON.parse(message.value!.toString()) as OrderPlaced;
        await tx.send({
          topic: 'payments',
          messages: [
            {
              key: order.orderId,
              value: JSON.stringify({ orderId: order.orderId, amount: order.total }),
              headers: { type: 'payment.requested' },
            },
          ],
        });
      }
      await tx.sendOffsets({
        consumerGroupId: GROUP_ID,
        topics: [
          { topic, partitions: [{ partition, offset: (Number(message.offset) + 1).toString() }] },
        ],
      });
      await tx.commit();
    } catch (error) {
      await tx.abort();
      throw error; // kafkajs не сдвинет позицию и прочитает запись снова
    }
  }

  async onApplicationShutdown() {
    await this.consumer.disconnect();
    await this.producer.disconnect();
  }
}

