type Envelope = {
  eventId: string;
  type: string;
  aggregateId: string;
  aggregateVersion: number;
};

const seen = new Set<string>(); // обработанные eventId
const versions = new Map<string, number>(); // последняя версия каждого заказа

function handle(event: Envelope): void {
  if (seen.has(event.eventId)) {
    console.log(`${event.eventId}: повтор, пропускаем`);
    return;
  }
  seen.add(event.eventId);
  const known = versions.get(event.aggregateId) ?? 0;
  if (event.aggregateVersion <= known) {
    console.log(`${event.eventId}: версия ${event.aggregateVersion} не новее ${known}, пропускаем`);
    return;
  }
  versions.set(event.aggregateId, event.aggregateVersion);
  console.log(`${event.eventId}: ${event.type}, заказ ${event.aggregateId} версии ${event.aggregateVersion}`);
}

const placed = { eventId: 'e-1', type: 'orders.order.placed.v1', aggregateId: 'A-1', aggregateVersion: 1 };
const cancelled = { eventId: 'e-2', type: 'orders.order.cancelled.v1', aggregateId: 'A-1', aggregateVersion: 2 };

handle(cancelled); // отмена обогнала оформление
handle(placed); // оформление пришло позже, после повтора
handle(cancelled); // повторная доставка отмены

