import { z } from 'zod';

/** Сервисы, которые публикуют события. */
export const producers = ['orders', 'payments', 'notifications', 'warehouse'] as const;
export type Producer = (typeof producers)[number];

const envelopeFields = {
  eventId: z.uuid(),
  schemaVersion: z.number().int().positive(),
  occurredAt: z.iso.datetime(), // UTC: 2026-10-11T09:15:42.120Z
  producer: z.enum(producers),
  aggregateId: z.uuid(),
  aggregateVersion: z.number().int().nonnegative(),
  correlationId: z.string().min(1).max(128).optional(),
  causationId: z.string().min(1).max(128).optional(),
};

/** Конверт с непроверенной нагрузкой: первый шаг любого потребителя. */
export const anyEventSchema = z.object({
  ...envelopeFields,
  type: z.string().regex(/^[a-z]+(\.[a-z-]+)+\.v\d+$/),
  payload: z.unknown(),
});
export type AnyEvent = z.infer<typeof anyEventSchema>;

/** Объявляет событие. Версия — часть имени: orders.order.placed.v1. */
export function defineEvent<Type extends string, Payload extends z.ZodType>(
  type: Type,
  producer: Producer,
  payload: Payload,
) {
  const match = /\.v(\d+)$/.exec(type);
  if (!match) throw new Error(`тип события должен кончаться на .vN: ${type}`);
  return {
    type,
    schemaVersion: Number(match[1]),
    producer,
    payload,
    /** Полная схема: конверт, тип-литерал и нагрузка этого типа. */
    schema: z.object({ ...envelopeFields, type: z.literal(type), payload }),
  };
}

type Definition = ReturnType<typeof defineEvent>;
export type EventOf<D extends Definition> = z.infer<D['schema']>;

/** Собирает конверт и проверяет его схемой события. */
export function createEvent<D extends Definition>(
  definition: D,
  input: {
    aggregateId: string;
    aggregateVersion: number;
    payload: z.input<D['payload']>;
    correlationId?: string;
    causationId?: string;
  },
): EventOf<D> {
  return definition.schema.parse({
    ...input,
    eventId: crypto.randomUUID(),
    type: definition.type,
    schemaVersion: definition.schemaVersion,
    occurredAt: new Date().toISOString(),
    producer: definition.producer,
  }) as EventOf<D>;
}

