import { Inject, Injectable, type OnModuleInit, ServiceUnavailableException } from '@nestjs/common';
import type { ClientKafkaProxy } from '@nestjs/microservices';
import type { AnyEvent } from '@shop/contracts';
import { lastValueFrom } from 'rxjs';
import { EventPublisher } from './event-publisher.js';

export const ORDERS_KAFKA = 'ORDERS_KAFKA';

@Injectable()
export class KafkaEventPublisher extends EventPublisher implements OnModuleInit {
  constructor(@Inject(ORDERS_KAFKA) private readonly kafka: ClientKafkaProxy) {
    super();
  }

  async onModuleInit() {
    await this.kafka.connect();
  }

  async publish(event: AnyEvent): Promise<void> {
    try {
      await lastValueFrom(
        this.kafka.emit('orders', {
          key: event.aggregateId, // все события заказа — в одну партицию
          value: event, // транспорт сам превратит объект в JSON
          headers: {
            type: event.type,
            eventId: event.eventId,
            ...(event.correlationId && { correlationId: event.correlationId }),
          },
        }),
      );
    } catch (error) {
      // как в главе 8: повторы исчерпаны — вызывающий код должен узнать, что события нет
      throw new ServiceUnavailableException(`${event.type} не записано в Kafka`, { cause: error });
    }
  }
}

