private async handle(
  channel: ChannelWrapper,
  spec: QueueSpec,
  message: ConsumeMessage,
  handler: EventHandler,
) {
  const attempt = Number(message.properties.headers?.[ATTEMPT_HEADER] ?? 0);
  let event: AnyEvent;
  try {
    // Шаг 1: тело — JSON, и в нём корректный конверт
    event = anyEventSchema.parse(JSON.parse(message.content.toString('utf8')));
  } catch {
    // Не конверт: повтор не поможет, сразу в DLQ
    const dlq = deadLetterQueueName(spec.name);
    return this.moveTo(channel, message, dlq, attempt, 'invalid');
  }
  // Шаг 2 — в обработчике; ошибки и повторы — как в главе 5
  await this.run(channel, spec, message, event, handler, attempt);
}

import type { Producer } from './envelope.js';

/** Обменник производителя: orders.events. */
export const eventsExchange = (producer: Producer) => `${producer}.events`;

export type QueueSpec = {
  name: string; // <потребитель>.<имя>
  bindings: { exchange: string; routingKey: string }[];
  prefetch: number;
};

/** Очередь потребителя и её привязки; ключ — полное имя типа события. */
export function defineQueue(
  consumer: Producer,
  name: string,
  bindings: { producer: Producer; types: string[] }[],
  prefetch = 16,
): QueueSpec {
  return {
    name: `${consumer}.${name}`,
    bindings: bindings.flatMap(({ producer, types }) =>
      types.map((routingKey) => ({ exchange: eventsExchange(producer), routingKey })),
    ),
    prefetch,
  };
}

