/** База или транзакция: у обеих одинаковые методы запросов. */
export type Executor = Pick<
  NodePgDatabase<Record<string, unknown>>,
  'execute' | 'insert' | 'select' | 'update' | 'delete'
>;

/** Кладёт событие в outbox. Вызывать только с транзакцией изменения! */
export async function enqueueEvent(tx: Executor, event: AnyEvent) {
  await tx.insert(outbox).values({
    eventId: event.eventId,
    type: event.type,
    exchange: eventsExchange(event.producer),
    envelope: event,
  });
}

import { ConflictException, Inject, Injectable } from '@nestjs/common';
import { createEvent, orderCancelled } from '@shop/contracts';
import { DATABASE, enqueueEvent } from '@shop/db';
import { OutboxRelay } from '@shop/messaging';
import { and, eq, sql } from 'drizzle-orm';
import type { Database } from './db/database.js';
import { orders } from './db/schema.js';
import { orderPlacedEvent, type PlaceOrderDto } from './order-events.js';

@Injectable()
export class OrdersService {
  constructor(
    @Inject(DATABASE) private readonly db: Database,
    private readonly relay: OutboxRelay,
  ) {}

  async place(dto: PlaceOrderDto) {
    const order = await this.db.transaction(async (tx) => {
      const [order] = await tx
        .insert(orders)
        .values({ ...dto, status: 'placed', version: 1 })
        .returning();
      await enqueueEvent(tx, orderPlacedEvent(order)); // та же транзакция
      return order;
    });
    this.relay.kick(); // commit уже был: ретранслятор увидит строку
    return { orderId: order.id, status: order.status };
  }

  async cancel(orderId: string, reason: string) {
    const order = await this.db.transaction(async (tx) => {
      const [order] = await tx
        .update(orders)
        .set({ status: 'cancelled', version: sql`${orders.version} + 1` })
        .where(and(eq(orders.id, orderId), eq(orders.status, 'placed')))
        .returning();
      if (!order) throw new ConflictException('order is not placed'); // откат
      await enqueueEvent(
        tx,
        createEvent(orderCancelled, {
          aggregateId: order.id,
          aggregateVersion: order.version, // 2: версия после изменения
          payload: { orderId: order.id, reason },
        }),
      );
      return order;
    });
    this.relay.kick();
    return { orderId: order.id, status: order.status };
  }
}

/**
 * Забирает до `limit` готовых событий под новую аренду одним коротким запросом.
 * Параллельные ретрансляторы пропускают строки друг друга, а истёкшая аренда
 * (ретранслятор упал) снова делает событие доступным.
 */
export async function claimOutboxBatch(
  db: Executor,
  options: { limit: number; leaseMs: number },
): Promise<ClaimedEvent[]> {
  const leaseToken = randomUUID();
  const result = await db.execute<{
    event_id: string;
    exchange: string;
    envelope: AnyEvent;
    attempts: number;
  }>(sql`
    update outbox
       set lease_token = ${leaseToken},
           lease_until = now() + make_interval(secs => ${options.leaseMs / 1000}),
           attempts = attempts + 1
     where event_id in (
       select event_id from outbox
        where status = 'pending'
          and available_at <= now()
          and (lease_until is null or lease_until < now())
        order by created_at
        limit ${options.limit}
        for update skip locked
     )
    returning event_id, exchange, envelope, attempts`);
  return result.rows.map((row) => ({
    eventId: row.event_id,
    exchange: row.exchange,
    envelope: row.envelope,
    attempts: row.attempts,
    leaseToken,
  }));
}

/** Помечает событие опубликованным, только если аренда всё ещё наша. */
export async function markOutboxPublished(db: Executor, eventId: string, leaseToken: string) {
  const rows = await db
    .update(outbox)
    .set({ status: 'published', publishedAt: new Date(), leaseToken: null, leaseUntil: null })
    .where(and(eq(outbox.eventId, eventId), eq(outbox.leaseToken, leaseToken)))
    .returning({ eventId: outbox.eventId });
  return rows.length === 1;
}

/** Возвращает событие в очередь ретранслятора не раньше чем через `delayMs`. */
export async function releaseOutboxEvent(
  db: Executor,
  eventId: string,
  leaseToken: string,
  options: { delayMs: number; error: string },
) {
  const rows = await db
    .update(outbox)
    .set({
      leaseToken: null,
      leaseUntil: null,
      availableAt: new Date(Date.now() + options.delayMs),
      lastError: options.error.slice(0, 1000),
    })
    .where(and(eq(outbox.eventId, eventId), eq(outbox.leaseToken, leaseToken)))
    .returning({ eventId: outbox.eventId });
  return rows.length === 1;
}

import {
  Inject,
  Injectable,
  Logger,
  type OnApplicationBootstrap,
  type OnApplicationShutdown,
} from '@nestjs/common';
import {
  claimOutboxBatch,
  DATABASE,
  type Executor,
  markOutboxPublished,
  purgePublishedOutbox,
  releaseOutboxEvent,
} from '@shop/db';
import { Messaging } from './messaging.js';

const INTERVAL_MS = 1000; // опрос, когда событий нет
const BATCH = 50;
const LEASE_MS = 30_000;
const KEEP_PUBLISHED_MS = 7 * 24 * 3600 * 1000;

@Injectable()
export class OutboxRelay implements OnApplicationBootstrap, OnApplicationShutdown {
  private readonly logger = new Logger(OutboxRelay.name);
  private timer: NodeJS.Timeout | undefined;
  private running = false;
  private stopped = false;
  private lastPurge = 0;

  constructor(
    @Inject(DATABASE) private readonly db: Executor,
    private readonly messaging: Messaging,
  ) {}

  onApplicationBootstrap() {
    this.schedule(0);
  }

  onApplicationShutdown() {
    this.stopped = true;
    clearTimeout(this.timer);
  }

  /** Вызывать после commit транзакции, которая положила события в outbox. */
  kick() {
    if (!this.running) this.schedule(0);
  }

  private schedule(delayMs: number) {
    if (this.stopped) return;
    clearTimeout(this.timer);
    this.timer = setTimeout(() => void this.tick(), delayMs);
  }

  /** Один проход: забрать пачку, опубликовать, пометить. */
  async tick(): Promise<number> {
    if (this.running) return 0;
    this.running = true;
    let published = 0;
    let full = false;
    try {
      const batch = await claimOutboxBatch(this.db, { limit: BATCH, leaseMs: LEASE_MS });
      full = batch.length === BATCH;
      for (const event of batch) {
        try {
          // Messaging.publish в виде из главы 9 (обменник и конверт):
          // промис выполняется после подтверждения брокера.
          await this.messaging.publish(event.exchange, event.envelope);
          if (await markOutboxPublished(this.db, event.eventId, event.leaseToken)) published++;
          else this.logger.warn(`Lease lost before marking ${event.eventId}`);
        } catch (error) {
          // 2 с, 4 с, 8 с … но не больше минуты.
          const delayMs = Math.min(60_000, 1000 * 2 ** Math.min(event.attempts, 6));
          await releaseOutboxEvent(this.db, event.eventId, event.leaseToken, {
            delayMs,
            error: (error as Error).message,
          }).catch(() => undefined); // не вышло — вернёт истечение аренды
        }
      }
      if (Date.now() - this.lastPurge > 3_600_000) {
        this.lastPurge = Date.now();
        await purgePublishedOutbox(this.db, new Date(Date.now() - KEEP_PUBLISHED_MS));
      }
    } catch (error) {
      this.logger.error(`Outbox relay pass failed: ${(error as Error).message}`);
    } finally {
      this.running = false;
      this.schedule(full ? 0 : INTERVAL_MS); // полная пачка — сразу следующая
    }
    return published;
  }
}

