/**
 * Замена messaging.publish в ретрансляторе, когда события идут в Kafka.
 * producer создан с idempotent: true и maxInFlightRequests: 1 (глава 8).
 */
export async function publishToKafka(producer: Producer, topic: string, event: AnyEvent) {
  await producer.send({
    topic,
    acks: -1, // ждать все синхронные реплики
    messages: [
      {
        key: event.aggregateId, // события одного заказа — в одну партицию
        value: JSON.stringify(event),
        headers: { type: event.type, eventId: event.eventId },
      },
    ],
  });
}

