import type { NodePgDatabase } from 'drizzle-orm/node-postgres';
import { inbox } from './schema.js';

export type Transaction = Parameters<
  Parameters<NodePgDatabase<Record<string, unknown>>['transaction']>[0]
>[0];

/**
 * Применяет локальный эффект потребителя один раз на пару (consumer, eventId):
 * отметка в inbox и эффект фиксируются одной транзакцией. Внешние эффекты
 * (письма, HTTP) внутри `effect` запрещены.
 */
export async function processOnce(
  db: NodePgDatabase<Record<string, unknown>>,
  message: { consumer: string; eventId: string; type: string },
  effect: (tx: Transaction) => Promise<void>,
): Promise<'processed' | 'duplicate'> {
  return db.transaction(async (tx) => {
    const inserted = await tx
      .insert(inbox)
      .values(message)
      .onConflictDoNothing()
      .returning({ eventId: inbox.eventId });
    if (inserted.length === 0) return 'duplicate';
    await effect(tx);
    return 'processed';
  });
}

