export const orderPlacedQueue = defineQueue('payments', 'order-placed', [
  { producer: 'orders', types: [orderPlaced.type] },
]);

@Injectable()
export class OrderPlacedConsumer implements OnApplicationBootstrap {
  private readonly logger = new Logger(OrderPlacedConsumer.name);

  constructor(
    @Inject(DATABASE) private readonly db: Database,
    private readonly messaging: Messaging,
  ) {}

  async onApplicationBootstrap() {
    await this.messaging.subscribe(orderPlacedQueue, async (message) => {
      const parsed = orderPlaced.schema.safeParse(message);
      if (!parsed.success) throw new PermanentError('invalid orders.order.placed.v1');
      const event = parsed.data;
      const outcome = await processOnce(
        this.db,
        { consumer: orderPlacedQueue.name, eventId: event.eventId, type: event.type },
        async (tx) => {
          await tx
            .insert(payments)
            .values({
              orderId: event.payload.orderId,
              amount: event.payload.total.amount,
              currency: event.payload.total.currency,
              status: 'pending', // списывать будет отдельный воркер
            })
            .onConflictDoNothing({ target: payments.orderId }); // тот же заказ, другой eventId
        },
      );
      if (outcome === 'duplicate') this.logger.log(`Duplicate ${event.eventId} skipped`);
      // Обработчик завершился после commit — только теперь Messaging отправит ack.
    });
  }
}

