import { sql } from 'drizzle-orm';
import type { Database } from './db/database.js';
import { orderStates } from './db/schema.js';

/** Новее побеждает: true, если состояние изменилось; повтор и старое — no-op. */
export async function applyOrderState(
  db: Database,
  orderId: string,
  status: 'placed' | 'cancelled',
  version: number,
) {
  const rows = await db
    .insert(orderStates)
    .values({ orderId, status, version })
    .onConflictDoUpdate({
      target: orderStates.orderId,
      set: { status, version },
      setWhere: sql`${orderStates.version} < ${version}`,
    })
    .returning({ orderId: orderStates.orderId });
  return rows.length > 0;
}

