@Injectable()
export class OrderEventsConsumer implements OnApplicationBootstrap {
  constructor(
    @Inject(DATABASE) private readonly db: Database,
    private readonly messaging: Messaging,
    private readonly worker: EmailWorker,
  ) {}

  async onApplicationBootstrap() {
    await this.messaging.subscribe(orderEventsQueue, async (message) => {
      const parsed = orderPlaced.schema.safeParse(message);
      if (!parsed.success) throw new PermanentError('invalid orders.order.placed.v1');
      const event = parsed.data;
      await processOnce(
        this.db,
        { consumer: orderEventsQueue.name, eventId: event.eventId, type: event.type },
        async (tx) => {
          // Не письмо, а намерение его отправить: строка в той же транзакции.
          await tx
            .insert(emailIntents)
            .values({
              sourceEventId: event.eventId,
              template: 'order-placed',
              customerId: event.payload.customerId,
              data: { orderId: event.payload.orderId, total: event.payload.total },
            })
            .onConflictDoNothing();
        },
      );
      this.worker.kick(); // commit уже был: воркер найдёт намерение
    });
  }
}

/** Тот же приём, что у ретранслятора: SKIP LOCKED и аренда. */
private async claim(limit: number): Promise<Claimed[]> {
  const leaseToken = randomUUID();
  const result = await this.db.execute<{
    id: string;
    customer_id: string;
    template: string;
    data: Record<string, unknown>;
    attempts: number;
  }>(sql`
    update email_intents
       set state = 'leased', lease_token = ${leaseToken},
           lease_until = now() + make_interval(secs => ${LEASE_MS / 1000}),
           attempts = attempts + 1
     where id in (
       select id from email_intents
        where (state in ('pending', 'retry_wait') and next_attempt_at <= now())
           or (state = 'leased' and lease_until < now())
        order by next_attempt_at
        limit ${limit}
        for update skip locked)
    returning id, customer_id, template, data, attempts`);
  return result.rows.map((row) => ({
    id: row.id,
    customerId: row.customer_id,
    template: row.template,
    data: row.data,
    attempts: row.attempts,
    leaseToken,
  }));
}

private async process(intent: Claimed) {
  try {
    const to = await this.recipients.emailOf(intent.customerId);
    const { id } = await this.mailer.send({
      to,
      template: intent.template,
      data: intent.data,
      idempotencyKey: intent.id, // одинаковый на всех попытках
    });
    await this.finish(intent, 'sent', { providerMessageId: id });
  } catch (error) {
    const lastError = (error as Error).message;
    if (error instanceof PermanentDeliveryError) {
      await this.finish(intent, 'failed', { lastError });
    } else if (error instanceof UnknownOutcomeError) {
      await this.finish(intent, 'unknown', { lastError }); // вслепую не повторяем
    } else {
      const delay = RETRY_DELAYS_MS[intent.attempts - 1];
      if (delay === undefined) await this.finish(intent, 'failed', { lastError });
      else
        await this.finish(intent, 'retry_wait', {
          lastError,
          nextAttemptAt: new Date(Date.now() + delay),
        });
    }
  }
}

/** Записывает исход, только если аренда всё ещё наша. */
private async finish(
  intent: Claimed,
  state: Intent['state'],
  fields: Partial<Pick<Intent, 'providerMessageId' | 'lastError' | 'nextAttemptAt'>>,
) {
  const rows = await this.db
    .update(emailIntents)
    .set({ state, leaseToken: null, leaseUntil: null, ...fields })
    .where(and(eq(emailIntents.id, intent.id), eq(emailIntents.leaseToken, intent.leaseToken)))
    .returning({ id: emailIntents.id });
  if (rows.length === 0) this.logger.warn(`Lease lost before recording ${intent.id}`);
}

