// Обычная очередь, без единственного активного потребителя:
// экземпляров warehouse может быть сколько угодно.
export const orderEventsQueue = defineQueue('warehouse', 'order-events', [
  { producer: 'orders', types: [orderPlaced.type, orderCancelled.type] },
]);

@Injectable()
export class KnownOrdersConsumer implements OnApplicationBootstrap {
  constructor(
    @Inject(DATABASE) private readonly db: Database,
    private readonly messaging: Messaging,
  ) {}

  async onApplicationBootstrap() {
    await this.messaging.subscribe(orderEventsQueue, async (message) => {
      const placed = orderPlaced.schema.safeParse(message);
      const cancelled = orderCancelled.schema.safeParse(message);
      const event = placed.success ? placed.data : cancelled.success ? cancelled.data : null;
      if (!event) throw new PermanentError(`invalid ${message.type}`);
      const status = event.type === orderPlaced.type ? 'placed' : 'cancelled';
      await this.db
        .insert(knownOrders)
        .values({
          orderId: event.payload.orderId,
          status,
          items: event.type === orderPlaced.type ? event.payload.items : null,
          version: event.aggregateVersion,
        })
        .onConflictDoUpdate({
          target: knownOrders.orderId,
          set: { status, version: event.aggregateVersion }, // состав не трогаем
          setWhere: sql`${knownOrders.version} < ${event.aggregateVersion}`, // новее побеждает
        });
    });
  }
}

