type Status = 'placed' | 'paid' | 'confirmed' | 'cancelled';

// Допустимые переходы: из какого статуса в какой можно попасть одним шагом
const transitions: Record<Status, Status[]> = {
  placed: ['paid', 'cancelled'],
  paid: ['confirmed', 'cancelled'],
  confirmed: [],
  cancelled: [],
};

function reachable(from: Status, to: Status): boolean {
  return transitions[from].some((next) => next === to || reachable(next, to));
}

function decide(current: Status, target: Status): 'apply' | 'defer' | 'skip' {
  if (transitions[current].includes(target)) return 'apply';
  if (reachable(current, target)) return 'defer'; // пришло раньше предыдущего шага
  return 'skip'; // дубль или устаревшее событие
}

let status: Status = 'placed';
const deferred: Status[] = [];

function receive(target: Status, note = '') {
  const decision = decide(status, target);
  if (decision === 'apply') status = target;
  if (decision === 'defer') deferred.push(target);
  console.log(`${target}${note}: ${decision}, статус ${status}`);
  if (decision !== 'apply') return;
  // после перехода пробуем применить отложенные
  for (const next of deferred.splice(0)) receive(next, ' (из отложенных)');
}

receive('confirmed'); // брокер доставил события не по порядку
receive('paid');
receive('paid'); // повторная доставка

import { Inject, Injectable } from '@nestjs/common';
import type { ClientKafka } from '@nestjs/microservices';
import { PermanentError } from '@shop/messaging';
import { lastValueFrom } from 'rxjs';

export const RETRY_TOPIC = 'orders.retry.1';
export const DEAD_LETTER_TOPIC = 'orders.dlt';
const MAX_ATTEMPTS = 4; // первая попытка и три повтора

export type FailedRecord = {
  topic: string;
  partition: number;
  offset: string;
  key: Buffer | string | null;
  value: unknown;
  headers?: Record<string, unknown>;
};

@Injectable()
export class KafkaRetryRouter {
  constructor(@Inject('KAFKA_RETRY') private readonly kafka: ClientKafka) {}

  /** Кладёт упавшую запись в retry-топик или в DLT; промис выполнится после ответа брокера. */
  async route(record: FailedRecord, error: unknown): Promise<void> {
    const attempt = Number(String(record.headers?.['x-attempt'] ?? 0)) + 1;
    const dead = error instanceof PermanentError || attempt >= MAX_ATTEMPTS;
    await lastValueFrom(
      this.kafka.emit(dead ? DEAD_LETTER_TOPIC : RETRY_TOPIC, {
        key: record.key, // тот же ключ — та же партиция и в новом топике
        value: record.value,
        headers: {
          'x-origin': `${record.topic}/${record.partition}/${record.offset}`,
          ...record.headers, // у повторной попытки x-origin уже есть и не перезапишется
          'x-attempt': String(attempt),
          'x-last-error': String(error instanceof Error ? error.message : error).slice(0, 500),
        },
      }),
    );
  }
}

import { type ArgumentsHost, Catch, type ExceptionFilter, Injectable } from '@nestjs/common';
import type { KafkaContext } from '@nestjs/microservices';
import { KafkaRetryRouter } from './kafka-retry.router.js';

@Catch()
@Injectable()
export class KafkaRetryFilter implements ExceptionFilter {
  constructor(private readonly router: KafkaRetryRouter) {}

  async catch(error: unknown, host: ArgumentsHost) {
    const context = host.switchToRpc().getContext<KafkaContext>();
    const message = context.getMessage();
    const topic = context.getTopic();
    const partition = context.getPartition();

    // Если переложить не удалось, исключение уйдёт в kafkajs:
    // оффсет не закоммитится, и запись будет прочитана снова.
    await this.router.route({ topic, partition, ...message }, error);
    await context.getConsumer().commitOffsets([
      { topic, partition, offset: (Number(message.offset) + 1).toString() },
    ]);
  }
}

