import { Injectable, type OnApplicationBootstrap, type OnApplicationShutdown } from '@nestjs/common';
import { type Consumer, Kafka } from 'kafkajs';
import { KafkaRetryRouter, RETRY_TOPIC } from './kafka-retry.router.js';
import { OrderStats } from './order-stats.js';

const DELAY_MS = 30_000;

/** Своя группа и свой потребитель: ожидание здесь не тормозит топик orders. */
@Injectable()
export class OrdersRetryConsumer implements OnApplicationBootstrap, OnApplicationShutdown {
  private readonly consumer: Consumer = new Kafka({
    clientId: 'analytics-retry',
    brokers: ['localhost:9092'],
  }).consumer({ groupId: 'analytics-retry' });

  constructor(
    private readonly stats: OrderStats,
    private readonly router: KafkaRetryRouter,
  ) {}

  async onApplicationBootstrap() {
    await this.consumer.connect();
    await this.consumer.subscribe({ topics: [RETRY_TOPIC] });
    await this.consumer.run({
      eachMessage: async ({ topic, partition, message, heartbeat }) => {
        // все записи топика ждут одинаково, поэтому ждать «голову» партиции не страшно
        await waitUntil(Number(message.timestamp) + DELAY_MS, heartbeat);
        try {
          await this.stats.record(JSON.parse(message.value?.toString() ?? 'null'));
        } catch (error) {
          await this.router.route({ topic, partition, ...message }, error);
        }
      },
    });
  }

  async onApplicationShutdown() {
    await this.consumer.disconnect();
  }
}

async function waitUntil(dueAt: number, heartbeat: () => Promise<void>) {
  while (Date.now() < dueAt) {
    await new Promise((resolve) => setTimeout(resolve, Math.min(dueAt - Date.now(), 3_000)));
    await heartbeat(); // ждём дольше sessionTimeout — значит, сообщаем, что живы
  }
}

export const orderSagas = pgTable('order_sagas', {
  orderId: uuid('order_id').primaryKey(),
  // шаг, ответа на который ждёт сага; done — сага закончена
  step: text('step', { enum: ['payment', 'stock', 'refund', 'done'] }).notNull(),
  status: text('status', { enum: ['running', 'confirmed', 'cancelled'] }).notNull(),
  deadline: timestamp('deadline', { withTimezone: true }), // срок шага; null, когда сага закончена
  version: integer('version').notNull(), // растёт с каждым переходом
});

import { Inject, Injectable } from '@nestjs/common';
import { DATABASE, enqueueEvent } from '@shop/db';
import { OutboxRelay } from '@shop/messaging';
import type { Database } from './db/database.js';
import { orders } from './db/schema.js';
import { orderPlacedEvent, type PlaceOrderDto } from './order-events.js';
import { OrderSagaService } from './saga/order-saga.service.js';

@Injectable()
export class OrdersService {
  constructor(
    @Inject(DATABASE) private readonly db: Database,
    private readonly relay: OutboxRelay,
    private readonly saga: OrderSagaService,
  ) {}

  async place(dto: PlaceOrderDto) {
    const order = await this.db.transaction(async (tx) => {
      const [order] = await tx
        .insert(orders)
        .values({ ...dto, status: 'placed', version: 1 })
        .returning();
      await enqueueEvent(tx, orderPlacedEvent(order)); // та же транзакция
      await this.saga.start(tx, order); // новое: сага начинается здесь же
      return order;
    });
    this.relay.kick(); // commit уже был: ретранслятор увидит строки
    return { orderId: order.id, status: order.status };
  }
}

const STEP_TIMEOUT_MS = 5 * 60_000; // срок ответа на каждом шаге
const deadline = () => new Date(Date.now() + STEP_TIMEOUT_MS);

export const sagaRepliesQueue = defineQueue('orders', 'saga-replies', [
  { producer: 'payments', types: [paymentCaptured.type, paymentFailed.type, paymentRefunded.type] },
  { producer: 'warehouse', types: [stockReserved.type, stockRejected.type] },
]);
const reply = z.discriminatedUnion('type', [
  paymentCaptured.schema,
  paymentFailed.schema,
  paymentRefunded.schema,
  stockReserved.schema,
  stockRejected.schema,
]);

type Saga = typeof orderSagas.$inferSelect;
type Definition = Parameters<typeof createEvent>[0]; // любое событие или команда

@Injectable()
export class OrderSagaService implements OnApplicationBootstrap {
  constructor(
    @Inject(DATABASE) private readonly db: Database,
    private readonly messaging: Messaging,
  ) {}

  async onApplicationBootstrap() {
    await this.messaging.subscribe(sagaRepliesQueue, (event) =>
      processOnce(
        this.db,
        { consumer: sagaRepliesQueue.name, eventId: event.eventId, type: event.type },
        (tx) => this.onReply(tx, event),
      ),
    );
  }

  /** Шаг 1. Вызывается из OrdersService.place в той же транзакции, что создаёт заказ. */
  async start(tx: Transaction, order: Order) {
    const saga = { orderId: order.id, step: 'payment', status: 'running', version: 1 } as const;
    await tx.insert(orderSagas).values({ ...saga, deadline: deadline() });
    await this.command(tx, saga, chargePayment, { orderId: order.id, amount: order.total });
  }

  private async onReply(tx: Transaction, raw: AnyEvent) {
    const parsed = reply.safeParse(raw);
    if (!parsed.success) throw new PermanentError(`invalid ${raw.type}`);
    const event = parsed.data;
    const [saga] = await tx
      .select()
      .from(orderSagas)
      .where(eq(orderSagas.orderId, event.payload.orderId))
      .for('update'); // ответ и проверка таймаута не изменят сагу одновременно
    if (!saga) throw new PermanentError(`no saga for order ${event.payload.orderId}`);

    switch (event.type) {
      case paymentCaptured.type:
        if (saga.step === 'payment') {
          const [order] = await tx.select().from(orders).where(eq(orders.id, saga.orderId));
          return this.next(tx, saga, 'stock', reserveStock, { orderId: saga.orderId, items: order.items });
        }
        // оплата прошла, когда заказ уже отменяют (например, по таймауту): вернуть деньги
        if (saga.step === 'refund' || saga.status === 'cancelled')
          return this.command(tx, saga, refundPayment, { orderId: saga.orderId });
        return;
      case paymentFailed.type:
        if (saga.step === 'payment') return this.finish(tx, saga, 'cancelled', 'payment failed');
        return;
      case stockReserved.type:
        if (saga.step === 'stock') return this.finish(tx, saga, 'confirmed');
        return;
      case stockRejected.type:
        // компенсация: склад отказал — возвращаем уже списанную оплату
        if (saga.step === 'stock') return this.next(tx, saga, 'refund', refundPayment, { orderId: saga.orderId });
        return;
      case paymentRefunded.type:
        if (saga.step === 'refund') return this.finish(tx, saga, 'cancelled', 'compensated');
        return;
    }
  }

/** Переход к следующему шагу и команда для него — в одной транзакции. */
private async next<D extends Definition>(
  tx: Transaction,
  saga: Saga,
  step: 'stock' | 'refund',
  command: D,
  payload: z.input<D['payload']>,
) {
  const moved = { ...saga, step, version: saga.version + 1 };
  await tx
    .update(orderSagas)
    .set({ step, deadline: deadline(), version: moved.version })
    .where(eq(orderSagas.orderId, saga.orderId));
  await this.command(tx, moved, command, payload);
}

/** Команда уходит через outbox: опубликует ретранслятор после commit. */
private async command<D extends Definition>(
  tx: Transaction,
  saga: Pick<Saga, 'orderId' | 'version'>,
  definition: D,
  payload: z.input<D['payload']>,
) {
  await enqueueEvent(
    tx,
    createEvent(definition, { aggregateId: saga.orderId, aggregateVersion: saga.version, payload }),
  );
}

private async finish(tx: Transaction, saga: Saga, status: 'confirmed' | 'cancelled', reason = '') {
  await tx
    .update(orderSagas)
    .set({ step: 'done', status, deadline: null, version: saga.version + 1 })
    .where(eq(orderSagas.orderId, saga.orderId));
  const [order] = await tx
    .update(orders)
    .set({ status, version: sql`${orders.version} + 1` })
    .where(eq(orders.id, saga.orderId))
    .returning();
  const aggregate = { aggregateId: order.id, aggregateVersion: order.version };
  await enqueueEvent(
    tx,
    status === 'confirmed'
      ? createEvent(orderConfirmed, { ...aggregate, payload: { orderId: order.id } })
      : createEvent(orderCancelled, { ...aggregate, payload: { orderId: order.id, reason } }),
  );
}

/** Отложенная проверка: шаг, не ответивший вовремя, компенсируем. */
@Interval(15_000)
async checkDeadlines() {
  await this.db.transaction(async (tx) => {
    const overdue = await tx
      .select()
      .from(orderSagas)
      .where(and(eq(orderSagas.status, 'running'), lt(orderSagas.deadline, new Date())))
      .limit(100)
      .for('update', { skipLocked: true }); // несколько экземпляров orders не возьмут одну сагу
    for (const saga of overdue) {
      // исход шага неизвестен: отменяем всё, что могло успеть произойти
      if (saga.step === 'stock') await this.command(tx, saga, releaseStock, { orderId: saga.orderId });
      await this.next(tx, saga, 'refund', refundPayment, { orderId: saga.orderId });
    }
  });
}

this.connection.on('blocked', ({ reason }) => {
  this.metrics.connectionBlocked.set(1);
  this.logger.warn({ msg: 'RabbitMQ blocked the connection', reason });
});
this.connection.on('unblocked', () => {
  this.metrics.connectionBlocked.set(0);
  this.logger.log({ msg: 'RabbitMQ unblocked the connection' });
});

