  readonly consumed = new Counter<'queue' | 'outcome'>({
    name: 'messaging_events_consumed_total',
    help: 'Обработанные события по очереди и исходу: processed, retried, dead_lettered.',
    labelNames: ['queue', 'outcome'],
    registers: [this.registry],
  });

  readonly handlerSeconds = new Histogram<'queue'>({
    name: 'messaging_handler_duration_seconds',
    help: 'Сколько работал обработчик, по очереди.',
    labelNames: ['queue'],
    buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10],
    registers: [this.registry],
  });

  readonly eventLag = new Histogram<'queue'>({
    name: 'messaging_event_lag_seconds',
    help: 'От occurredAt события до конца его обработки, по очереди.',
    labelNames: ['queue'],
    buckets: [0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10, 30, 60, 300, 900],
    registers: [this.registry],
  });

  readonly connectionBlocked = new Gauge({
    name: 'messaging_connection_blocked',
    help: '1, пока RabbitMQ блокирует публикующее соединение (аларм ресурса).',
    registers: [this.registry],
  });

  constructor() {
    this.registry.setDefaultLabels({ service: process.env.SERVICE_NAME ?? 'payments' });
    collectDefaultMetrics({ register: this.registry }); // процесс и Node: CPU, память, event loop
  }
}

/** Отдельный порт только для GET /metrics: Ingress приложения его не публикует. */
@Injectable()
export class MetricsServer implements OnApplicationBootstrap, OnApplicationShutdown {
  private server: Server | undefined;

  constructor(private readonly metrics: Metrics) {}

  onApplicationBootstrap() {
    const { registry } = this.metrics;
    this.server = createServer((req, res) => {
      if (req.method !== 'GET' || req.url !== '/metrics') {
        res.writeHead(404).end();
        return;
      }
      registry.metrics().then(
        (body) => res.writeHead(200, { 'content-type': registry.contentType }).end(body),
        () => res.writeHead(500).end(),
      );
    });
    this.server.listen(Number(process.env.METRICS_PORT ?? 9464));
  }

  onApplicationShutdown() {
    this.server?.close();
    this.server?.closeAllConnections(); // Prometheus держит соединение между опросами
  }
}

@Global()
@Module({ providers: [Metrics, MetricsServer], exports: [Metrics] })
export class MetricsModule {}

private async handle(
  channel: ChannelWrapper,
  spec: QueueSpec,
  message: ConsumeMessage,
  handler: EventHandler,
) {
  const queue = spec.name;
  const stopTimer = this.metrics.handlerSeconds.startTimer({ queue });
  const attempt = Number(message.properties.headers?.[ATTEMPT_HEADER] ?? 0);
  let event: AnyEvent;
  try {
    // Тело — JSON, и в нём корректный конверт (глава 9)
    event = anyEventSchema.parse(JSON.parse(message.content.toString('utf8')));
  } catch {
    this.metrics.consumed.inc({ queue, outcome: 'dead_lettered' });
    stopTimer();
    return this.moveTo(channel, message, deadLetterQueueName(queue), attempt, 'invalid');
  }
  // Идентификаторы — в логах; в метках метрик их не бывает
  const log = {
    queue,
    eventId: event.eventId,
    type: event.type,
    correlationId: event.correlationId ?? event.eventId,
    attempt,
  };
  try {
    await withConsumerSpan(queue, message.properties.headers, () => handler(event, { attempt }));
    channel.ack(message);
    const lagMs = Math.max(0, Date.now() - Date.parse(event.occurredAt));
    this.metrics.consumed.inc({ queue, outcome: 'processed' });
    this.metrics.eventLag.observe({ queue }, lagMs / 1000);
    this.logger.log({ msg: 'Event handled', ...log, lagMs });
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    const dead = error instanceof PermanentError || attempt >= spec.retryDelaysMs.length;
    const outcome = dead ? 'dead_lettered' : 'retried';
    this.metrics.consumed.inc({ queue, outcome });
    this.logger.warn({ msg: 'Event handling failed', ...log, outcome, err: reason });
    const target = dead ? deadLetterQueueName(queue) : retryQueueName(queue, attempt);
    await this.moveTo(channel, message, target, attempt + 1, reason);
  } finally {
    stopTimer();
  }
}

/** Сколько событий ждёт публикации и сколько секунд ждёт самое старое. */
export async function outboxBacklog(db: Executor) {
  const result = await db.execute<{ pending: number; oldest: number }>(sql`
    select count(*)::int as pending,
           coalesce(extract(epoch from now() - min(created_at)), 0)::float8 as oldest
      from outbox
     where status = 'pending'`);
  const row = result.rows[0];
  return { pending: row?.pending ?? 0, oldestSeconds: row?.oldest ?? 0 };
}

