/** Бэклог outbox читается из базы при каждом опросе Prometheus. */
@Injectable()
export class OutboxMetrics {
  constructor(metrics: Metrics, @Inject(DATABASE) db: Executor) {
    // Обе метрики ждут один и тот же запрос: один SELECT на опрос
    let reading: ReturnType<typeof outboxBacklog> | undefined;
    const read = () =>
      (reading ??= outboxBacklog(db).finally(() => {
        reading = undefined;
      }));
    new Gauge({
      name: 'outbox_pending_events',
      help: 'Закоммиченные, но ещё не опубликованные события.',
      registers: [metrics.registry],
      async collect() {
        this.set((await read()).pending);
      },
    });
    new Gauge({
      name: 'outbox_oldest_pending_age_seconds',
      help: 'Возраст самого старого неопубликованного события; 0 — outbox пуст.',
      registers: [metrics.registry],
      async collect() {
        this.set((await read()).oldestSeconds);
      },
    });
  }
}

