import { propagation, ROOT_CONTEXT, SpanKind, SpanStatusCode, trace } from '@opentelemetry/api';

const tracer = trace.getTracer('shop-messaging');

/** Обработка сообщения — продолжение трассы того, кто его отправил. */
export function withConsumerSpan<T>(
  queue: string,
  headers: Record<string, unknown> | undefined,
  work: () => Promise<T>,
): Promise<T> {
  const parent = propagation.extract(ROOT_CONTEXT, headers ?? {}); // traceparent из заголовков
  return tracer.startActiveSpan(
    `process ${queue}`,
    {
      kind: SpanKind.CONSUMER,
      attributes: { 'messaging.system': 'rabbitmq', 'messaging.destination.name': queue },
    },
    parent,
    async (span) => {
      try {
        return await work(); // всё, что обработчик запишет в outbox, унаследует этот контекст
      } catch (error) {
        span.recordException(error as Error);
        span.setStatus({ code: SpanStatusCode.ERROR });
        throw error;
      } finally {
        span.end();
      }
    },
  );
}

