import { context, propagation, ROOT_CONTEXT, type TextMapGetter } from '@opentelemetry/api';

/** В Kafka значения заголовков приходят как Buffer: пропагатору нужны строки. */
const kafkaHeaders: TextMapGetter<KafkaJS.IHeaders> = {
  keys: (carrier) => Object.keys(carrier),
  get: (carrier, key) => {
    const value = carrier[key];
    return Array.isArray(value) ? value.map(String) : value?.toString();
  },
};

async onApplicationBootstrap() {
  await this.consumer.connect();
  await this.consumer.subscribe({ topics: ['orders'] });
  await this.consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      // Обработка из главы 7 — внутри контекста трассы из заголовков записи
      const parent = propagation.extract(ROOT_CONTEXT, message.headers ?? {}, kafkaHeaders);
      await context.with(parent, async () => {
        if (message.headers?.type?.toString() === 'order.placed' && message.value) {
          const order = JSON.parse(message.value.toString()) as OrderPlaced;
          await this.notifier.orderPlaced(order);
        }
      });
      await this.consumer.commitOffsets([
        { topic, partition, offset: (Number(message.offset) + 1).toString() },
      ]);
      // timestamp — миллисекунды строкой: время создания записи
      const lagMs = Math.max(0, Date.now() - Number(message.timestamp));
      this.lag.observe({ topic }, lagMs / 1000);
    },
  });
}

async onApplicationShutdown() {
  // Дождаться текущего eachMessage, выйти из группы: партиции сразу уйдут другим
  await this.consumer.disconnect();
}

