const perInstance = (prefetch * 1000) / msEach; // сколько успевает один экземпляр
const minInstances = Math.ceil(inWork / prefetch);
const withHeadroom = Math.ceil(inWork / (prefetch * 0.7)); // загрузка не выше 70 %

