console.log(`один экземпляр: ${perInstance} в секунду`);
console.log(`экземпляров минимум: ${minInstances}`);
console.log(`с запасом до 70 %: ${withHeadroom}`);

const mbPerSecond = 2; // поток в топик orders после сжатия, МБ/с
const retentionDays = 7; // retention.ms топика
const replicationFactor = 3;

const perCopyGb = Math.round((mbPerSecond * 86_400 * retentionDays) / 1000);
const allCopiesGb = perCopyGb * replicationFactor;

console.log(`одна копия за ${retentionDays} суток: ${perCopyGb} ГБ`);
