/** Обработчики, которые уже работают: их ждёт плавная остановка. */
export class InFlight {
  private readonly running = new Set<Promise<unknown>>();

  get size() {
    return this.running.size;
  }

  /** Запомнить работу; она сама уйдёт из списка, когда закончится. */
  track(work: Promise<unknown>) {
    const done = work.catch(() => undefined).finally(() => this.running.delete(done));
    this.running.add(done);
  }

  /** true — всё закончилось; false — вышло время, часть ещё работает. */
  async drain(timeoutMs: number): Promise<boolean> {
    let timer: NodeJS.Timeout | undefined;
    const timeout = new Promise<boolean>((resolve) => {
      timer = setTimeout(() => resolve(false), timeoutMs);
    });
    const all = Promise.all([...this.running]).then(() => true);
    try {
      return await Promise.race([all, timeout]);
    } finally {
      clearTimeout(timer);
    }
  }
}

await channel.consume(
  spec.name,
  (message) => this.inFlight.track(this.handle(channel, spec, message, handler)),
  { prefetch: spec.prefetch },
);

// ...

/** Шаги 1–2: перестать брать новые сообщения и дождаться тех, что в работе. */
async beforeApplicationShutdown() {
  await Promise.allSettled(this.consumers.map((channel) => channel.cancelAll()));
  const drained = await this.inFlight.drain(this.options.drainTimeoutMs ?? 20_000);
  if (!drained) {
    this.logger.warn({ msg: 'Shutdown: handlers still running', inFlight: this.inFlight.size });
  }
}

/** Шаги 3–4: закрыть каналы, потом соединение. Неподтверждённое вернётся в очередь. */
async onApplicationShutdown() {
  await Promise.allSettled(this.consumers.map((channel) => channel.close()));
  await this.publisher.close().catch(() => undefined);
  await this.connection.close().catch(() => undefined);
}

